  text?: string;
  isMe: boolean;
  time: string;
  status: 'sent' | 'delivered' | 'read';
  type: 'text' | 'image' | 'video' | 'location' | 'file' | 'audio' | 'course' | 'verse' | 'prayer' | 'question' | 'room-invite' | 'assignment' | 'notice';
  content?: string; 
  meta?: any; 
}

interface Conversation {
  id: string;
  userId: string;
  userName: string;
  userAvatar: string;
  isOnline: boolean;
  role: string;
  isGroup?: boolean;
}

