// --- Group Info Screen ---
const GroupInfoView: React.FC<{ conv: Conversation, onBack: () => void }> = ({ conv, onBack }) => {
  const members = [
    { name: '张神学生', avatar: MOCK_USER.avatar, status: 'online', isMe: true },
    { name: '教务处', avatar: 'https://ui-avatars.com/api/?name=Admin&background=0f172a&color=fff', isOrg: true },
    { name: '林恩典', avatar: 'https://picsum.photos/100/100?random=u2' },
    { name: '李保罗', avatar: 'https://ui-avatars.com/api/?name=Paul+Lee&background=1e3a8a&color=fff' },
    { name: '张彼得', avatar: 'https://picsum.photos/100/100?random=u3' }
  ];

  return (
    <div className="fixed inset-0 z-[100] bg-white flex flex-col animate-slide-in-right overflow-hidden">
      <div className="bg-white border-b border-slate-100 px-4 py-3 pt-safe-top flex items-center justify-between shrink-0">
        <button onClick={onBack} className="p-2 -ml-2 rounded-full hover:bg-slate-100 transition">
          <ChevronLeft size={24} className="text-slate-800" />
        </button>
        <h2 className="font-bold text-slate-900 text-base">聊天信息({members.length})</h2>
        <div className="w-8"></div>
      </div>

      <div className="flex-1 overflow-y-auto bg-slate-50">
        <div className="bg-white p-5 grid grid-cols-5 gap-y-6 mb-2">
          {members.map((m, i) => (
            <div key={i} className="flex flex-col items-center">
              <div className="relative">
                <img src={m.avatar} className="w-12 h-12 rounded-lg object-cover shadow-sm" />
                {m.isMe && <div className="absolute -top-1 -right-1 w-3 h-3 bg-amber-400 border-2 border-white rounded-full"></div>}
                {m.isOrg && <div className="absolute -top-1 -right-1 w-3 h-3 bg-blue-500 border-2 border-white rounded-full"></div>}
              </div>
              <span className={`text-[10px] mt-1.5 truncate w-full text-center ${m.isMe || m.isOrg ? 'text-blue-600 font-bold' : 'text-slate-500'}`}>{m.name}</span>
            </div>
          ))}
          <div className="flex flex-col items-center">
            <button className="w-12 h-12 rounded-lg border-2 border-dashed border-slate-200 flex items-center justify-center text-slate-300 hover:border-blue-400 hover:text-blue-400 transition-colors">
              <Plus size={24} />
            </button>
            <span className="text-[10px] mt-1.5 text-slate-400">添加</span>
          </div>
        </div>

        <div className="space-y-2">
          <div className="bg-white">
            <button className="w-full px-5 py-4 flex items-center justify-between border-b border-slate-50 active:bg-slate-50 transition-colors">
              <span className="text-sm font-medium text-slate-800">群聊名称</span>
              <div className="flex items-center text-slate-400 text-sm">
                <span className="mr-2">{conv.userName}</span>
                <ChevronRight size={18} />
