            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

const ChatView: React.FC<ChatViewProps> = ({ onBack, initialChatId, onJoinRoom, onCourseClick }) => {
  const [activeChatId, setActiveChatId] = useState<string | null>(initialChatId || null);
  const [messages, setMessages] = useState<Record<string, Message[]>>(() => {
    try {
        const saved = localStorage.getItem('amas_chat_messages');
        return saved ? JSON.parse(saved) : INITIAL_MESSAGES;
    } catch (e) {
        return INITIAL_MESSAGES;
    }
  });
  const [inputText, setInputText] = useState("");
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showPlusMenu, setShowPlusMenu] = useState(false);
  const [showGroupInfo, setShowGroupInfo] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordDuration, setRecordDuration] = useState(0);

  // Picker States
  const [activePicker, setActivePicker] = useState<'none' | 'course' | 'scripture' | 'prayer' | 'question' | 'assignment'>('none');

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const durationRef = useRef(0);
  const timerRef = useRef<any>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (initialChatId) setActiveChatId(initialChatId);
  }, [initialChatId]);

  useEffect(() => {
    localStorage.setItem('amas_chat_messages', JSON.stringify(messages));
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, activeChatId, isRecording]);

  const activeConv = INITIAL_CONVERSATIONS.find(c => c.id === (activeChatId || 'c1')) || INITIAL_CONVERSATIONS[0];
  const currentMessages = activeChatId ? (messages[activeChatId] || []) : [];

  const sendMessage = (msgData: Partial<Message>) => {
    if (!activeChatId) return;
    const newMessage: Message = {
      id: Date.now().toString(),
      isMe: true,
      time: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}),
      status: 'sent',
      type: 'text',
      ...msgData
    };
    setMessages(prev => ({
      ...prev,
      [activeChatId]: [...(prev[activeChatId] || []), newMessage]
    }));
    setShowEmojiPicker(false);
    setShowPlusMenu(false);
    setActivePicker('none');
  };

  const handleSendText = () => {
    if (!inputText.trim()) return;
    sendMessage({ text: inputText, type: 'text' });
    setInputText("");
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        sendMessage({ type: 'image', content: ev.target?.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, isAssignment: boolean = false) => {
    if (e.target.files && e.target.files[0]) {
       const file = e.target.files[0];
       sendMessage({ 
         type: isAssignment ? 'assignment' : 'file', 
         text: file.name, 
         meta: `${(file.size / 1024 / 1024).toFixed(2)} MB` 
       });
    }
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      mediaRecorder.ondataavailable = (e) => audioChunksRef.current.push(e.data);
      mediaRecorder.onstop = () => {
        sendMessage({ type: 'audio', meta: `${durationRef.current}s` });
        stream.getTracks().forEach(t => t.stop());
      };
      mediaRecorder.start();
      setIsRecording(true);
      setRecordDuration(0);
      durationRef.current = 0;
      timerRef.current = window.setInterval(() => {
        setRecordDuration(prev => { durationRef.current = prev + 1; return prev + 1; });
      }, 1000);
    } catch (e) { alert("无法访问麦克风"); }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    clearInterval(timerRef.current);
    setIsRecording(false);
  };

  const plusMenuItems = [
    { label: '相册', icon: ImageIcon, color: 'bg-amber-100 text-amber-500', action: () => fileInputRef.current?.click() },
    { label: '推荐课程', icon: BookOpen, color: 'bg-blue-100 text-blue-500', action: () => setActivePicker('course') },
    { label: '学术提问', icon: QuestionIcon, color: 'bg-cyan-100 text-cyan-500', action: () => setActivePicker('question') },
    { label: '递交作业', icon: ClipboardList, color: 'bg-indigo-100 text-indigo-500', action: () => setActivePicker('assignment') },
    { label: '分享经文', icon: Scroll, color: 'bg-orange-100 text-orange-500', action: () => setActivePicker('scripture') },
    { label: '发布代祷', icon: Heart, color: 'bg-rose-100 text-rose-500', action: () => setActivePicker('prayer') },
    { label: '语音房间', icon: Radio, color: 'bg-emerald-100 text-emerald-500', action: () => onJoinRoom?.({ id: 'room-1', type: 'fellowship', label: '交通室', icon: Coffee, color: 'text-emerald-500', bg: 'bg-emerald-50', desc: '来自聊天的邀请', action: 'voice' }) },
    { label: '文件', icon: FileBox, color: 'bg-slate-100 text-slate-500', action: () => setActivePicker('assignment') }
  ];

  // --- Specialized Message Components ---
  const CourseBubble = ({ courseId }: { courseId: string }) => {
    const course = MOCK_COURSES.find(c => c.id === courseId) || MOCK_COURSES[0];
    return (
      <div 
        onClick={() => onCourseClick?.(course.id)}
        className="bg-white border border-slate-100 rounded-2xl overflow-hidden shadow-sm hover:shadow-md transition-all cursor-pointer w-64"
      >
        <img src={course.thumbnail} className="w-full h-32 object-cover" alt={course.title} />
        <div className="p-3">
            <h4 className="font-bold text-slate-900 text-sm line-clamp-1">{course.title}</h4>
            <p className="text-[10px] text-slate-500 mt-1 flex items-center"><User size={10} className="mr-1"/> {course.instructor}</p>
            <div className="mt-2 pt-2 border-t border-slate-50 flex items-center justify-between text-blue-600">
                <span className="text-[10px] font-bold">查看详情</span>
                <ChevronRight size={14} />
            </div>
        </div>
      </div>
    );
  };

  const VerseBubble = ({ content }: { content: string }) => (
    <div className="bg-amber-50 border border-amber-200 rounded-2xl p-4 shadow-sm w-64 font-serif">
      <div className="flex items-center text-amber-700 mb-2">
        <Scroll size={14} className="mr-1.5"/>
        <span className="text-[10px] font-bold uppercase tracking-widest">每日经文</span>
      </div>
      <p className="text-sm text-amber-900 leading-relaxed italic">"{content}"</p>
    </div>
  );

  const PrayerBubble = ({ content }: { content: string }) => (
    <div className="bg-rose-50 border border-rose-200 rounded-2xl p-4 shadow-sm w-64">
      <div className="flex items-center text-rose-600 mb-2">
        <HandHeart size={14} className="mr-1.5"/>
        <span className="text-[10px] font-bold uppercase tracking-widest">代祷请求</span>
      </div>
      <p className="text-sm text-slate-800 leading-relaxed">{content}</p>
      <button className="mt-3 w-full py-1.5 bg-rose-500 text-white rounded-lg text-[10px] font-bold shadow-sm active:scale-95 transition-transform">加入代祷</button>
    </div>
  );

  const AssignmentBubble = ({ filename, size }: { filename: string, size: string }) => (
    <div className="bg-white border border-indigo-100 rounded-2xl p-3 shadow-sm w-64 flex items-center">
      <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-xl flex items-center justify-center mr-3 shrink-0">
        <FileText size={20} />
      </div>
      <div className="min-w-0 flex-1">
        <h4 className="text-xs font-bold text-slate-900 truncate">{filename}</h4>
        <p className="text-[10px] text-slate-400 mt-0.5">{size} • 已提交作业</p>
      </div>
    </div>
  );

  return (
    <div className="flex flex-col h-screen bg-[#f1f3f5] relative max-w-md mx-auto overflow-hidden">
        {showGroupInfo && <GroupInfoView conv={activeConv} onBack={() => setShowGroupInfo(false)} />}

        {/* Hidden Inputs */}
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />

        {/* --- Specialized Pickers --- */}
        {activePicker !== 'none' && (
          <div className="fixed inset-0 z-[110] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-fade-in" onClick={() => setActivePicker('none')}>
            <div className="bg-white w-full max-sm rounded-3xl p-6 shadow-2xl animate-scale-in relative" onClick={e => e.stopPropagation()}>
                <button onClick={() => setActivePicker('none')} className="absolute top-4 right-4 text-slate-400"><X size={20}/></button>

                {activePicker === 'course' && (
                  <div className="flex flex-col h-[70vh]">
                    <h3 className="font-bold text-lg text-slate-900 mb-4 flex items-center"><BookOpen size={20} className="mr-2 text-blue-600"/> 推荐课程</h3>
                    <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                       {MOCK_COURSES.map(c => (
                         <div 
                            key={c.id} 
                            onClick={() => sendMessage({ type: 'course', content: c.id })}
                            className="p-3 bg-slate-50 border border-slate-100 rounded-2xl flex items-center cursor-pointer hover:bg-blue-50 transition-colors"
                         >
                           <img src={c.thumbnail} className="w-12 h-12 rounded-lg object-cover mr-3"/>
                           <div className="flex-1 min-w-0">
                             <p className="text-sm font-bold text-slate-900 truncate">{c.title}</p>
                             <p className="text-[10px] text-slate-500">{c.instructor}</p>
                           </div>
                           <Send size={16} className="text-blue-500 ml-2"/>
                         </div>
                       ))}
                    </div>
                  </div>
                )}

                {activePicker === 'scripture' && (
                  <div>
                    <h3 className="font-bold text-lg text-slate-900 mb-4 flex items-center"><Scroll size={20} className="mr-2 text-orange-500"/> 分享经文</h3>
                    <textarea 
                      id="verseInput"
                      className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 text-sm font-serif min-h-[120px] outline-none focus:ring-2 focus:ring-orange-500" 
                      placeholder="输入想要分享的经文内容或金句..."
                      autoFocus
                    />
                    <button 
                      onClick={() => {
                        const val = (document.getElementById('verseInput') as HTMLTextAreaElement).value;
                        if(val.trim()) sendMessage({ type: 'verse', text: val });
                      }}
                      className="w-full mt-4 bg-orange-500 text-white py-3 rounded-2xl font-bold active:scale-95 transition-transform"
                    >发送经文</button>
                  </div>
                )}

                {activePicker === 'prayer' && (
                  <div>
                    <h3 className="font-bold text-lg text-slate-900 mb-4 flex items-center"><Heart size={20} className="mr-2 text-rose-500"/> 发布代祷</h3>
                    <textarea 
                      id="prayerInput"
                      className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 text-sm min-h-[120px] outline-none focus:ring-2 focus:ring-rose-500" 
                      placeholder="写下您的代祷事项..."
                      autoFocus
                    />
                    <button 
                      onClick={() => {
                        const val = (document.getElementById('prayerInput') as HTMLTextAreaElement).value;
                        if(val.trim()) sendMessage({ type: 'prayer', text: val });
                      }}
                      className="w-full mt-4 bg-rose-500 text-white py-3 rounded-2xl font-bold active:scale-95 transition-transform"
                    >发起代祷</button>
                  </div>
                )}

                {activePicker === 'question' && (
                  <div>
                    <h3 className="font-bold text-lg text-slate-900 mb-4 flex items-center"><QuestionIcon size={20} className="mr-2 text-cyan-600"/> 学术提问</h3>
                    <p className="text-xs text-slate-500 mb-4 leading-relaxed">向教授或同学请教关于神学研究、课程作业的问题。</p>
                    <textarea 
                      id="questionInput"
                      className="w-full bg-slate-50 border border-slate-200 rounded-2xl p-4 text-sm min-h-[120px] outline-none focus:ring-2 focus:ring-cyan-600" 
                      placeholder="请详细描述您的问题..."
                      autoFocus
                    />
                    <button 
                      onClick={() => {
                        const val = (document.getElementById('questionInput') as HTMLTextAreaElement).value;
                        if(val.trim()) sendMessage({ type: 'question', text: val });
                      }}
                      className="w-full mt-4 bg-cyan-600 text-white py-3 rounded-2xl font-bold active:scale-95 transition-transform"
                    >提交问题</button>
                  </div>
                )}

                {activePicker === 'assignment' && (
                   <div>
                    <h3 className="font-bold text-lg text-slate-900 mb-4 flex items-center"><ClipboardList size={20} className="mr-2 text-indigo-600"/> 递交文件/作业</h3>
                    <div className="p-10 border-2 border-dashed border-slate-200 rounded-[2rem] flex flex-col items-center justify-center text-slate-400 bg-slate-50 hover:bg-slate-100 transition-colors cursor-pointer" onClick={() => {
                        const inp = document.createElement('input');
                        inp.type = 'file';
                        inp.onchange = (e) => handleFileUpload(e as any, true);
                        inp.click();
                    }}>
                        <FileUp size={48} className="mb-4 text-indigo-300" />
                        <span className="text-sm font-bold text-slate-600">点击上传文件</span>
                        <span className="text-[10px] mt-2">支持 PDF, DOCX, ZIP 等格式</span>
                    </div>
                  </div>
                )}

            </div>
          </div>
        )}

        {/* Header */}
        <div className="bg-white border-b border-slate-200 px-4 py-3 flex items-center justify-between pt-safe-top shrink-0 shadow-sm z-10">
            <div className="flex items-center">
                <button onClick={onBack} className="p-2 -ml-2 rounded-full hover:bg-slate-100 transition mr-1">
                    <ChevronLeft size={24} className="text-slate-800" />
                </button>
                <div className="flex items-center">
                    <div className="relative">
                        <img src={activeConv.userAvatar} className="w-10 h-10 rounded-full object-cover shadow-sm" />
                        {activeConv.isOnline && <div className="absolute bottom-0 right-0 w-3 h-3 bg-emerald-500 border-2 border-white rounded-full"></div>}
                    </div>
                    <div className="ml-3">
                        <h2 className="text-[15px] font-bold text-slate-900 leading-tight">{activeConv.userName}</h2>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">{activeConv.role}</p>
                    </div>
                </div>
            </div>
            <button onClick={() => setShowGroupInfo(true)} className="p-2 -mr-2 rounded-full hover:bg-slate-100 transition text-slate-600">
                <MoreVertical size={20} />
            </button>
        </div>

        {/* Message Stream */}
        <div className="flex-1 overflow-y-auto p-4 space-y-5 scrollbar-hide bg-[#f1f3f5]">
            {currentMessages.map((msg) => (
                <div key={msg.id} className={`flex w-full ${msg.isMe ? 'justify-end' : 'justify-start'} animate-fade-in`}>
                    {!msg.isMe && (
                        <div className="mr-3 shrink-0">
                            <img src={activeConv.userAvatar} className="w-9 h-9 rounded-lg object-cover shadow-sm" />
                        </div>
                    )}
                    <div className={`max-w-[85%] flex flex-col ${msg.isMe ? 'items-end' : 'items-start'}`}>
                        {msg.type === 'text' && (
                           <div className={`p-3 rounded-[1.2rem] shadow-sm text-sm leading-relaxed ${msg.isMe ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white text-slate-800 rounded-tl-none border border-slate-100'}`}>
                             <p>{msg.text}</p>
                           </div>
                        )}
                        {msg.type === 'image' && (
                           <div className="rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xs">
                              <img src={msg.content} className="w-full h-auto object-cover max-h-72" />
                           </div>
                        )}
                        {msg.type === 'course' && <CourseBubble courseId={msg.content || ''} />}
                        {msg.type === 'verse' && <VerseBubble content={msg.text || ''} />}
                        {msg.type === 'prayer' && <PrayerBubble content={msg.text || ''} />}
                        {msg.type === 'assignment' && <AssignmentBubble filename={msg.text || ''} size={msg.meta || ''} />}
                        {msg.type === 'question' && (
                           <div className="bg-cyan-50 border border-cyan-200 rounded-2xl p-4 shadow-sm w-64">
                              <div className="flex items-center text-cyan-700 mb-2">
                                <QuestionIcon size={14} className="mr-1.5"/>
                                <span className="text-[10px] font-bold uppercase tracking-widest">学术提问</span>
                              </div>
                              <p className="text-sm text-slate-800 leading-relaxed font-bold">{msg.text}</p>
                              <div className="mt-3 pt-2 border-t border-cyan-100 flex items-center text-[9px] text-cyan-600 font-bold">
                                 <Clock size={10} className="mr-1"/> 待回复
                              </div>
                           </div>
                        )}
                        {msg.type === 'audio' && (
                          <div className={`flex items-center space-x-3 p-3 rounded-[1.2rem] shadow-sm text-sm ${msg.isMe ? 'bg-blue-600 text-white' : 'bg-white text-slate-800 border border-slate-100'}`}>
                            <PlayCircle size={20} />
                            <div className="flex flex-col">
                               <div className="w-24 h-1.5 bg-white/20 rounded-full"></div>
                               <span className="text-[10px] opacity-70 mt-1">语音消息 {msg.meta}</span>
                            </div>
                          </div>
                        )}

                        <div className="mt-1 flex items-center px-1">
                            <span className="text-[9px] text-slate-400 font-medium">{msg.time}</span>
                            {msg.isMe && msg.status === 'read' && <CheckCircle size={10} className="ml-1 text-blue-500" />}
                        </div>
                    </div>
                    {msg.isMe && (
                        <div className="ml-3 shrink-0">
                            <img src={MOCK_USER.avatar} className="w-9 h-9 rounded-lg object-cover shadow-sm" />
                        </div>
                    )}
                </div>
            ))}
            <div ref={messagesEndRef} />
        </div>

        {/* Plus Menu (Mockup Image 1) */}
        {showPlusMenu && (
            <div className="bg-white border-t border-slate-200 animate-slide-up px-6 pt-6 pb-12 shrink-0 z-20">
               <div className="flex items-center mb-8">
                  <button onClick={() => setShowPlusMenu(false)} className="mr-4 text-slate-400 hover:text-slate-600">
                    <X size={24} />
                  </button>
                  <div className="flex-1 bg-slate-100 rounded-full px-4 py-2 flex items-center border border-slate-200">
                    <span className="text-sm text-slate-400">发送消息...</span>
                    <Smile size={20} className="ml-auto text-slate-400" />
                  </div>
                  <Mic size={24} className="ml-4 text-slate-400" />
               </div>

               <div className="grid grid-cols-4 gap-y-8">
                 {plusMenuItems.map((item, idx) => (
                   <div key={idx} className="flex flex-col items-center">
                     <button 
                        onClick={item.action}
                        className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center transition-all active:scale-95 shadow-sm ${item.color}`}
                     >
                       <item.icon size={28} strokeWidth={2} />
                     </button>
                     <span className="text-[11px] mt-2.5 text-slate-600 font-bold">{item.label}</span>
                   </div>
                 ))}
               </div>
            </div>
        )}

        {/* Input Bar (Image 2 Style) */}
        {!showPlusMenu && (
            <div className="bg-white border-t border-slate-200 p-3 pb-[calc(env(safe-area-inset-bottom)+8px)] shrink-0 z-20">
                <div className="flex items-center space-x-3">
                    <button 
                      onClick={() => setShowPlusMenu(true)}
                      className="p-1.5 text-slate-400 hover:text-blue-600 transition-colors"
                    >
                        <Plus size={32} strokeWidth={2.5} />
                    </button>

                    <div className="flex-1 bg-[#f1f3f5] rounded-full flex items-center px-4 py-2.5 transition-all border border-transparent focus-within:border-blue-100 focus-within:bg-white shadow-inner">
                        <input 
                            type="text" 
                            value={inputText}
                            onChange={(e) => setInputText(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleSendText()}
                            placeholder="发送消息..."
                            className="w-full bg-transparent border-none outline-none text-sm text-slate-800 placeholder:text-slate-400 font-medium"
                        />
                        <button onClick={() => setShowEmojiPicker(!showEmojiPicker)} className="ml-2 text-slate-400 hover:text-slate-600 transition">
                            <Smile size={22} />
                        </button>
                    </div>

                    {inputText.trim() ? (
                        <button 
                            onClick={handleSendText}
                            className="bg-blue-600 text-white p-2.5 rounded-full shadow-md active:scale-95 animate-scale-in"
                        >
                            <Send size={20} fill="white" />
                        </button>
                    ) : (
                        <button 
                           onClick={isRecording ? stopRecording : startRecording}
                           className={`p-2.5 rounded-full transition-all ${isRecording ? 'bg-rose-500 text-white shadow-lg animate-pulse' : 'bg-[#f1f3f5] text-slate-600'}`}
                        >
                            <Mic size={24} />
                        </button>
                    )}
                </div>
            </div>
        )}
    </div>
  );
};

