                           </div>
                        )}
                        {msg.type === 'course' && <CourseBubble courseId={msg.content || ''} />}
                        {msg.type === 'verse' && <VerseBubble content={msg.text || ''} />}
                        {msg.type === 'prayer' && <PrayerBubble content={msg.text || ''} />}
                        {msg.type === 'assignment' && <AssignmentBubble filename={msg.text || ''} size={msg.meta || ''} />}
                        {msg.type === 'question' && (
                           <div className="bg-cyan-50 border border-cyan-200 rounded-2xl p-4 shadow-sm w-64">
                              <div className="flex items-center text-cyan-700 mb-2">
                                <QuestionIcon size={14} className="mr-1.5"/>
                                <span className="text-[10px] font-bold uppercase tracking-widest">学术提问</span>
                              </div>
                              <p className="text-sm text-slate-800 leading-relaxed font-bold">{msg.text}</p>
                              <div className="mt-3 pt-2 border-t border-cyan-100 flex items-center text-[9px] text-cyan-600 font-bold">
                                 <Clock size={10} className="mr-1"/> 待回复
                              </div>
                           </div>
                        )}
                        {msg.type === 'audio' && (
                          <div className={`flex items-center space-x-3 p-3 rounded-[1.2rem] shadow-sm text-sm ${msg.isMe ? 'bg-blue-600 text-white' : 'bg-white text-slate-800 border border-slate-100'}`}>
                            <PlayCircle size={20} />
                            <div className="flex flex-col">
                               <div className="w-24 h-1.5 bg-white/20 rounded-full"></div>
                               <span className="text-[10px] opacity-70 mt-1">语音消息 {msg.meta}</span>
                            </div>
                          </div>
                        )}

                        <div className="mt-1 flex items-center px-1">
                            <span className="text-[9px] text-slate-400 font-medium">{msg.time}</span>
                            {msg.isMe && msg.status === 'read' && <CheckCircle size={10} className="ml-1 text-blue-500" />}
                        </div>
                    </div>
                    {msg.isMe && (
                        <div className="ml-3 shrink-0">
                            <img src={MOCK_USER.avatar} className="w-9 h-9 rounded-lg object-cover shadow-sm" />
                        </div>
                    )}
                </div>
            ))}
            <div ref={messagesEndRef} />
        </div>

        {/* Plus Menu */}
        {showPlusMenu && (
            <div className="bg-white border-t border-slate-200 animate-slide-up px-6 pt-6 pb-12 shrink-0 z-20">
               <div className="flex items-center mb-8">
                  <button onClick={() => setShowPlusMenu(false)} className="mr-4 text-slate-400 hover:text-slate-600">
                    <X size={24} />
                  </button>
                  <div className="flex-1 bg-[#f1f3f5] rounded-full px-4 py-2 flex items-center border border-slate-100">
                    <span className="text-sm text-slate-400">发送消息...</span>
                    <Smile size={20} className="ml-auto text-slate-400" />
                  </div>
                  <Mic size={24} className="ml-4 text-slate-400" />
               </div>

               <div className="grid grid-cols-4 gap-y-8">
                 {plusMenuItems.map((item, idx) => (
                   <div key={idx} className="flex flex-col items-center">
                     <button 
                        onClick={item.action}
                        className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center transition-all active:scale-95 shadow-sm ${item.color}`}
                     >
                       <item.icon size={28} strokeWidth={2} />
                     </button>
                     <span className="text-[11px] mt-2.5 text-slate-600 font-bold">{item.label}</span>
                   </div>
                 ))}
               </div>
            </div>
        )}

        {/* Input Bar - Redesigned to match the provided screenshot */}
        {!showPlusMenu && (
            <div className="bg-white p-3 pb-[calc(env(safe-area-inset-bottom)+12px)] shrink-0 z-20 shadow-[0_-1px_0_rgba(0,0,0,0.05)]">
                <div className="flex items-center">
                    {/* Plus Icon - Thinner stroke and more minimal spacing */}
                    <button 
                      onClick={() => setShowPlusMenu(true)}
                      className="p-2 text-slate-400 hover:text-blue-600 transition-colors mr-1"
                    >
                        <Plus size={28} strokeWidth={1.5} />
                    </button>

                    {/* Input Pill - Matched screenshot colors and inner items */}
                    <div className="flex-1 bg-[#f1f3f5] rounded-full flex items-center px-4 h-11 transition-all border border-transparent focus-within:border-blue-100 focus-within:bg-[#ebedef]">
                        <input 
                            type="text" 
                            value={inputText}
                            onChange={(e) => setInputText(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleSendText()}
                            placeholder="发送消息..."
                            className="flex-1 bg-transparent border-none outline-none text-[15px] text-slate-800 placeholder:text-slate-400 font-medium"
                        />
                        {/* Smiley Icon inside the pill */}
                        <button onClick={() => setShowEmojiPicker(!showEmojiPicker)} className="ml-2 text-slate-400 hover:text-slate-600 transition">
                            <Smile size={24} strokeWidth={1.5} />
                        </button>
                    </div>

                    {/* Right Action Button - Matched the circular Mic icon in the screenshot */}
                    <div className="ml-3">
                        {inputText.trim() ? (
                            <button 
                                onClick={handleSendText}
                                className="bg-blue-600 text-white w-10 h-10 rounded-full shadow-md active:scale-95 animate-scale-in flex items-center justify-center"
                            >
                                <Send size={20} fill="white" />
                            </button>
                        ) : (
                            <button 
                               onClick={isRecording ? stopRecording : startRecording}
                               className={`w-11 h-11 rounded-full flex items-center justify-center transition-all ${isRecording ? 'bg-rose-500 text-white shadow-lg animate-pulse' : 'bg-[#f1f3f5] text-slate-500'}`}
                            >
                                <Mic size={24} strokeWidth={1.5} />
                            </button>
                        )}
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

