const ChatView: React.FC<ChatViewProps> = ({ onBack, initialChatId, onJoinRoom, onCourseClick }) => {
  const [activeChatId, setActiveChatId] = useState<string | null>(initialChatId || null);
  const [messages, setMessages] = useState<Record<string, Message[]>>(() => {
    try {
        const saved = localStorage.getItem('amas_chat_messages');
        return saved ? JSON.parse(saved) : INITIAL_MESSAGES;
    } catch (e) {
        return INITIAL_MESSAGES;
    }
  });
  const [inputText, setInputText] = useState("");
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showPlusMenu, setShowPlusMenu] = useState(false);
  const [showGroupInfo, setShowGroupInfo] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordDuration, setRecordDuration] = useState(0);

  // Picker States
  const [activePicker, setActivePicker] = useState<'none' | 'course' | 'scripture' | 'prayer' | 'question' | 'assignment' | 'room'>('none');

  // Room creation state
  const [roomName, setRoomName] = useState("");
  const [selectedRoomType, setSelectedRoomType] = useState<RoomType>('fellowship');

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const durationRef = useRef(0);
  const timerRef = useRef<any>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (initialChatId) setActiveChatId(initialChatId);
  }, [initialChatId]);

  useEffect(() => {
    localStorage.setItem('amas_chat_messages', JSON.stringify(messages));
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, activeChatId, isRecording]);

  const activeConv = INITIAL_CONVERSATIONS.find(c => c.id === (activeChatId || 'c1')) || INITIAL_CONVERSATIONS[0];
  const currentMessages = activeChatId ? (messages[activeChatId] || []) : [];

  const sendMessage = (msgData: Partial<Message>) => {
    if (!activeChatId) return;
    const newMessage: Message = {
      id: Date.now().toString(),
      isMe: true,
      time: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}),
      status: 'sent',
      type: 'text',
      ...msgData
    };
    setMessages(prev => ({
      ...prev,
      [activeChatId]: [...(prev[activeChatId] || []), newMessage]
    }));
    setShowEmojiPicker(false);
    setShowPlusMenu(false);
    setActivePicker('none');
  };

  const handleSendText = () => {
    if (!inputText.trim()) return;
    sendMessage({ text: inputText, type: 'text' });
    setInputText("");
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        sendMessage({ type: 'image', content: ev.target?.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, isAssignment: boolean = false) => {
    if (e.target.files && e.target.files[0]) {
       const file = e.target.files[0];
       sendMessage({ 
         type: isAssignment ? 'assignment' : 'file', 
         text: file.name, 
         meta: `${(file.size / 1024 / 1024).toFixed(2)} MB` 
       });
    }
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      mediaRecorder.ondataavailable = (e) => audioChunksRef.current.push(e.data);
      mediaRecorder.onstop = () => {
        sendMessage({ type: 'audio', meta: `${durationRef.current}s` });
        stream.getTracks().forEach(t => t.stop());
      };
      mediaRecorder.start();
      setIsRecording(true);
      setRecordDuration(0);
      durationRef.current = 0;
      timerRef.current = window.setInterval(() => {
        setRecordDuration(prev => { durationRef.current = prev + 1; return prev + 1; });
      }, 1000);
    } catch (e) { alert("无法访问麦克风"); }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    clearInterval(timerRef.current);
    setIsRecording(false);
  };

  const plusMenuItems = [
    { label: '相册', icon: ImageIcon, color: 'bg-amber-100 text-amber-500', action: () => fileInputRef.current?.click() },
    { label: '推荐课程', icon: BookOpen, color: 'bg-blue-100 text-blue-500', action: () => setActivePicker('course') },
    { label: '学术提问', icon: QuestionIcon, color: 'bg-cyan-100 text-cyan-500', action: () => setActivePicker('question') },
    { label: '递交作业', icon: ClipboardList, color: 'bg-indigo-100 text-indigo-500', action: () => setActivePicker('assignment') },
    { label: '分享经文', icon: Scroll, color: 'bg-orange-100 text-orange-500', action: () => setActivePicker('scripture') },
    { label: '发布代祷', icon: Heart, color: 'bg-rose-100 text-rose-500', action: () => setActivePicker('prayer') },
    { label: '语音房间', icon: Radio, color: 'bg-emerald-100 text-emerald-500', action: () => setActivePicker('room') },
    { label: '文件', icon: FileBox, color: 'bg-slate-100 text-slate-500', action: () => {
        const input = document.createElement('input');
        input.type = 'file';
        input.onchange = (e) => handleFileUpload(e as any);
        input.click();
    } }
  ];

  const handleCreateRoomAction = () => {
    if (!roomName.trim()) return;
    const config = THEME_CONFIGS[selectedRoomType];
    const newRoom: Room = {
      id: `room-${Date.now()}`,
      type: selectedRoomType,
      label: roomName,
      icon: config.icon,
      color: config.color,
      bg: config.bg,
      desc: config.desc,
      action: 'voice',
      isCustom: true,
      hostId: 'me'
    };

    // Send room invite message to the chat
    sendMessage({ 
      type: 'room-invite', 
      content: `邀请加入：${roomName}`,
      meta: newRoom 
    });

    // Join the room
    onJoinRoom?.(newRoom);

    setActivePicker('none');
    setRoomName("");
    setShowPlusMenu(false);
  };

  // --- Specialized Message Components ---
  const CourseBubble = ({ courseId }: { courseId: string }) => {
    const course = MOCK_COURSES.find(c => c.id === courseId) || MOCK_COURSES[0];
    return (
      <div 
        onClick={() => onCourseClick?.(course.id)}
        className="bg-white border border-slate-100 rounded-2xl overflow-hidden shadow-sm hover:shadow-md transition-all cursor-pointer w-64"
      >
        <img src={course.thumbnail} className="w-full h-32 object-cover" alt={course.title} />
        <div className="p-3">
            <h4 className="font-bold text-slate-900 text-sm line-clamp-1">{course.title}</h4>
            <p className="text-[10px] text-slate-500 mt-1 flex items-center"><User size={10} className="mr-1"/> {course.instructor}</p>
            <div className="mt-2 pt-2 border-t border-slate-50 flex items-center justify-between text-blue-600">
                <span className="text-[10px] font-bold">查看详情</span>
                <ChevronRight size={14} />
            </div>
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-screen bg-[#f1f3f5] relative max-w-md mx-auto overflow-hidden">
        {/* Hidden Inputs */}
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />

        {/* --- Specialized Pickers --- */}
        {activePicker !== 'none' && (
          <div className="fixed inset-0 z-[110] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-fade-in" onClick={() => setActivePicker('none')}>
            <div className="bg-white w-full max-sm rounded-[2rem] p-6 shadow-2xl animate-scale-in relative" onClick={e => e.stopPropagation()}>
                <button onClick={() => setActivePicker('none')} className="absolute top-5 right-5 text-slate-400"><X size={22}/></button>

                {activePicker === 'course' && (
                  <div className="flex flex-col h-[70vh]">
                    <h3 className="font-bold text-lg text-slate-900 mb-4 flex items-center"><BookOpen size={20} className="mr-2 text-blue-600"/> 推荐课程</h3>
                    <div className="flex-1 overflow-y-auto pr-2 space-y-2">
                       {MOCK_COURSES.map(c => (
                         <div 
                            key={c.id} 
                            onClick={() => sendMessage({ type: 'course', content: c.id })}
                            className="p-3 bg-slate-50 border border-slate-100 rounded-2xl flex items-center cursor-pointer hover:bg-blue-50 transition-colors"
                         >
                           <img src={c.thumbnail} className="w-12 h-12 rounded-lg object-cover mr-3"/>
                           <div className="flex-1 min-w-0">
                             <p className="text-sm font-bold text-slate-900 truncate">{c.title}</p>
                             <p className="text-[10px] text-slate-500">{c.instructor}</p>
                           </div>
                           <Send size={16} className="text-blue-500 ml-2"/>
                         </div>
                       ))}
                    </div>
                  </div>
                )}

                {activePicker === 'scripture' && (
                  <div>
                    <h3 className="font-bold text-lg text-slate-900 mb-4 flex items-center"><Scroll size={20} className="mr-2 text-orange-500"/> 分享经文</h3>
                    <div className="bg-[#f1f3f5] rounded-[1.5rem] p-4 mb-4">
                      <textarea 
                        id="verseInput"
                        className="w-full bg-transparent text-black text-[15px] font-serif min-h-[120px] outline-none border-none placeholder:text-slate-400" 
                        placeholder="输入想要分享的经文内容或金句..."
                        autoFocus
                      />
                    </div>
                    <button 
                      onClick={() => {
                        const val = (document.getElementById('verseInput') as HTMLTextAreaElement).value;
                        if(val.trim()) sendMessage({ type: 'verse', text: val });
                      }}
                      className="w-full bg-orange-500 text-white py-4 rounded-[1.2rem] font-bold active:scale-95 transition-transform"
                    >发送经文</button>
                  </div>
                )}

                {activePicker === 'prayer' && (
                  <div>
                    <h3 className="font-bold text-lg text-slate-900 mb-4 flex items-center"><Heart size={20} className="mr-2 text-rose-500"/> 发布代祷</h3>
