                    </div>
                    <button 
                      onClick={() => {
                        const val = (document.getElementById('questionInput') as HTMLTextAreaElement).value;
                        if(val.trim()) sendMessage({ type: 'question', text: val });
                      }}
                      className="w-full bg-[#7ec4cf] text-white py-4 rounded-[1.2rem] font-bold active:scale-95 transition-transform"
                    >提交问题</button>
                  </div>
