                {activePicker === 'assignment' && (
                   <div>
                    <h3 className="font-bold text-lg text-slate-900 mb-4 flex items-center"><ClipboardList size={20} className="mr-2 text-indigo-600"/> 递交文件/作业</h3>
                    <div className="p-10 border-2 border-dashed border-slate-200 rounded-[2rem] flex flex-col items-center justify-center text-slate-400 bg-slate-50 hover:bg-slate-100 transition-colors cursor-pointer" onClick={() => {
                        const inp = document.createElement('input');
