const ChatView: React.FC<ChatViewProps> = ({ onBack, initialChatId, onJoinRoom, onCourseClick }) => {
  const [activeChatId, setActiveChatId] = useState<string | null>(initialChatId || null);
  const [messages, setMessages] = useState<Record<string, Message[]>>(() => {
    try {
        const saved = localStorage.getItem('amas_chat_messages');
        return saved ? JSON.parse(saved) : INITIAL_MESSAGES;
    } catch (e) {
        return INITIAL_MESSAGES;
    }
  });
  const [inputText, setInputText] = useState("");
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [showPlusMenu, setShowPlusMenu] = useState(false);
  const [showGroupInfo, setShowGroupInfo] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [recordDuration, setRecordDuration] = useState(0);

  // Picker States
  const [activePicker, setActivePicker] = useState<'none' | 'course' | 'scripture' | 'prayer' | 'question' | 'assignment' | 'room'>('none');

  // Room creation state
  const [roomName, setRoomName] = useState("");
  const [selectedRoomType, setSelectedRoomType] = useState<RoomType>('fellowship');

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const durationRef = useRef(0);
  const timerRef = useRef<any>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (initialChatId) setActiveChatId(initialChatId);
  }, [initialChatId]);

  useEffect(() => {
    localStorage.setItem('amas_chat_messages', JSON.stringify(messages));
  }, [messages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, activeChatId, isRecording]);

  const activeConv = INITIAL_CONVERSATIONS.find(c => c.id === (activeChatId || 'c1')) || INITIAL_CONVERSATIONS[0];
  const currentMessages = activeChatId ? (messages[activeChatId] || []) : [];

  const sendMessage = (msgData: Partial<Message>) => {
    if (!activeChatId) return;
    const newMessage: Message = {
      id: Date.now().toString(),
      isMe: true,
      time: new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}),
      status: 'sent',
      type: 'text',
      ...msgData
    };
    setMessages(prev => ({
      ...prev,
      [activeChatId]: [...(prev[activeChatId] || []), newMessage]
    }));
    setShowEmojiPicker(false);
    setShowPlusMenu(false);
    setActivePicker('none');
  };

  const handleSendText = () => {
    if (!inputText.trim()) return;
    sendMessage({ text: inputText, type: 'text' });
    setInputText("");
  };

  const handleEmojiClick = (emoji: string) => {
    setInputText(prev => prev + emoji);
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        sendMessage({ type: 'image', content: ev.target?.result as string });
      };
      reader.readAsDataURL(e.target.files[0]);
    }
  };

  const startRecording = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];
      mediaRecorder.ondataavailable = (e) => audioChunksRef.current.push(e.data);
      mediaRecorder.onstop = () => {
        sendMessage({ type: 'audio', meta: `${durationRef.current}s` });
        stream.getTracks().forEach(t => t.stop());
      };
      mediaRecorder.start();
      setIsRecording(true);
      setRecordDuration(0);
      durationRef.current = 0;
      timerRef.current = window.setInterval(() => {
        setRecordDuration(prev => { durationRef.current = prev + 1; return prev + 1; });
      }, 1000);
    } catch (e) { alert("无法访问麦克风"); }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    clearInterval(timerRef.current);
    setIsRecording(false);
  };

  const plusMenuItems = [
    { label: '相册', icon: ImageIcon, color: 'bg-[#fff7e6] text-[#ffa940]', action: () => fileInputRef.current?.click() },
    { label: '推荐课程', icon: BookOpen, color: 'bg-[#e6f7ff] text-[#1890ff]', action: () => setActivePicker('course') },
    { label: '学术提问', icon: QuestionIcon, color: 'bg-[#e6fffb] text-[#13c2c2]', action: () => setActivePicker('question') },
    { label: '递交作业', icon: ClipboardList, color: 'bg-[#f0f5ff] text-[#2f54eb]', action: () => setActivePicker('assignment') },
    { label: '分享经文', icon: Scroll, color: 'bg-[#fff2e8] text-[#fa541c]', action: () => setActivePicker('scripture') },
    { label: '发布代祷', icon: Heart, color: 'bg-[#fff1f0] text-[#ff4d4f]', action: () => setActivePicker('prayer') },
    { label: '语音房间', icon: Radio, color: 'bg-[#f6ffed] text-[#52c41a]', action: () => setActivePicker('room') },
    { label: '文件', icon: FileBox, color: 'bg-[#f5f5f5] text-[#8c8c8c]', action: () => {
        const inp = document.createElement('input');
        inp.type = 'file';
        inp.onchange = (e) => {
            const file = (e.target as any).files[0];
            if(file) sendMessage({ type: 'file', text: file.name, meta: `${(file.size / 1024).toFixed(1)} KB` });
        };
        inp.click();
    } }
  ];

  const handleCreateRoomAction = () => {
    if (!roomName.trim()) return;
    const config = THEME_CONFIGS[selectedRoomType];
    const newRoom: Room = {
      id: `room-${Date.now()}`,
      type: selectedRoomType,
      label: roomName,
      icon: config.icon,
      color: config.color,
      bg: config.bg,
      desc: config.desc,
      action: 'voice',
      isCustom: true,
      hostId: 'me'
    };

    // Create room and send invite message
    onJoinRoom?.(newRoom);
    sendMessage({ type: 'room-invite', meta: newRoom });

    setActivePicker('none');
    setRoomName("");
    setShowPlusMenu(false);
  };

  // --- Specialized Message Components ---
  const CourseBubble = ({ courseId }: { courseId: string }) => {
    const course = MOCK_COURSES.find(c => c.id === courseId) || MOCK_COURSES[0];
    return (
      <div 
        onClick={() => onCourseClick?.(course.id)}
        className="bg-white rounded-2xl overflow-hidden shadow-sm border border-slate-100 cursor-pointer w-64 group"
      >
        <div className="relative h-36">
           <img src={course.thumbnail} className="w-full h-full object-cover" alt={course.title} />
           <div className="absolute inset-0 bg-black/5 group-hover:bg-transparent transition-colors"></div>
        </div>
        <div className="p-3">
            <h4 className="font-bold text-black text-sm line-clamp-1">{course.title}</h4>
            <p className="text-[11px] text-slate-400 mt-1 flex items-center">
              <User size={10} className="mr-1 opacity-60"/> {course.instructor}
            </p>
            <div className="mt-2 pt-2 border-t border-slate-50 flex items-center justify-between text-blue-500">
                <span className="text-[11px] font-bold">查看详情</span>
                <ChevronRight size={14} />
            </div>
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-screen bg-[#f7f8fa] relative max-w-md mx-auto overflow-hidden">
        {/* Header */}
        <div className="bg-white border-b border-slate-100 px-4 py-3 flex items-center justify-between pt-safe-top shrink-0 z-10">
            <div className="flex items-center">
                <button onClick={onBack} className="p-2 -ml-2 rounded-full hover:bg-slate-100 transition mr-1">
                    <ChevronLeft size={24} className="text-slate-800" />
                </button>
                <div className="flex items-center">
                    <div className="relative">
                        <img src={activeConv.userAvatar} className="w-10 h-10 rounded-full object-cover shadow-sm" />
                        {activeConv.isOnline && <div className="absolute bottom-0 right-0 w-3 h-3 bg-emerald-500 border-2 border-white rounded-full"></div>}
                    </div>
                    <div className="ml-3">
                        <h2 className="text-[15px] font-bold text-slate-900 leading-tight">{activeConv.userName}</h2>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">{activeConv.role}</p>
                    </div>
                </div>
            </div>
            <button onClick={() => setShowGroupInfo(true)} className="p-2 -mr-2 rounded-full hover:bg-slate-100 transition text-slate-400">
                <MoreVertical size={20} />
            </button>
        </div>

        {/* Message Stream */}
        <div className="flex-1 overflow-y-auto p-4 space-y-6 scrollbar-hide bg-[#f7f8fa]">
            {currentMessages.map((msg) => (
                <div key={msg.id} className={`flex w-full ${msg.isMe ? 'justify-end' : 'justify-start'} animate-fade-in`}>
                    {!msg.isMe && (
                        <div className="mr-3 shrink-0">
                            <img src={activeConv.userAvatar} className="w-10 h-10 rounded-lg object-cover shadow-sm" />
                        </div>
                    )}
                    <div className={`max-w-[85%] flex flex-col ${msg.isMe ? 'items-end' : 'items-start'}`}>
                        {msg.type === 'text' && (
                           <div className={`p-3 rounded-2xl shadow-sm text-[15px] leading-relaxed ${msg.isMe ? 'bg-[#3b82f6] text-white rounded-tr-none' : 'bg-white text-black rounded-tl-none border border-slate-100'}`}>
                             <p>{msg.text}</p>
                           </div>
                        )}
                        {msg.type === 'image' && (
                           <div className="rounded-2xl overflow-hidden border border-slate-100 shadow-sm max-w-xs">
                              <img src={msg.content} className="w-full h-auto object-cover max-h-72" />
                           </div>
                        )}
                        {msg.type === 'course' && <CourseBubble courseId={msg.content || ''} />}

                        {msg.type === 'prayer' && (
                           <div className="bg-[#fff1f0] border border-[#ffa39e] rounded-2xl p-4 shadow-sm w-64">
                             <div className="flex items-center text-[#cf1322] mb-2">
                               <Heart size={14} className="mr-2" fill="currentColor"/>
                               <span className="text-[10px] font-black uppercase tracking-widest">发布代祷</span>
                             </div>
                             <p className="text-[15px] text-black leading-relaxed font-bold mb-4">{msg.text}</p>
                             <button className="w-full py-3 bg-[#ff4d4f] text-white rounded-xl text-[13px] font-bold shadow-sm active:scale-95 transition-all">发起代祷</button>
                           </div>
                        )}

                        {msg.type === 'question' && (
                           <div className="bg-[#e6fffb] border border-[#87e8de] rounded-2xl p-4 shadow-sm w-64">
                              <div className="flex items-center text-[#13c2c2] mb-2">
                                <QuestionIcon size={14} className="mr-2"/>
                                <span className="text-[10px] font-black uppercase tracking-widest">学术提问</span>
                              </div>
                              <p className="text-[15px] text-black leading-relaxed font-bold mb-3">{msg.text}</p>
                              <div className="pt-2 border-t border-[#87e8de]/50 flex items-center text-[10px] text-[#13c2c2] font-bold">
                                 <Clock size={12} className="mr-1.5"/> 待回复
                              </div>
                           </div>
                        )}

                        {msg.type === 'audio' && (
                          <div className={`flex items-center space-x-3 p-3 rounded-2xl shadow-sm min-w-[120px] ${msg.isMe ? 'bg-[#3b82f6] text-white' : 'bg-white text-black border border-slate-100'}`}>
                            <PlayCircle size={24} />
                            <div className="flex-1">
                               <div className="h-1 bg-white/30 rounded-full w-full mb-1"></div>
                               <span className="text-[11px] font-bold opacity-90">语音消息 {msg.meta}</span>
                            </div>
                          </div>
                        )}

                        {msg.type === 'room-invite' && msg.meta && (
                           <div onClick={() => onJoinRoom?.(msg.meta)} className="bg-gradient-to-br from-emerald-50 to-emerald-100 border border-emerald-200 rounded-2xl p-4 shadow-sm w-64 cursor-pointer hover:shadow-md transition-all active:scale-[0.98]">
                              <div className="flex items-center text-emerald-600 mb-2">
                                <Radio size={14} className="mr-1.5 animate-pulse"/>
                                <span className="text-[10px] font-black uppercase tracking-widest">语音邀请</span>
                              </div>
                              <h4 className="text-sm font-black text-emerald-900 truncate mb-1">{msg.meta.label}</h4>
                              <p className="text-[11px] text-emerald-700/70 mb-3 line-clamp-1">{msg.meta.desc}</p>
