                        <span className="text-[10px] font-bold text-slate-400">添加</span>
                    </button>
                </div>

                <div className="bg-white rounded-3xl overflow-hidden divide-y divide-slate-50">
                    <button className="w-full px-5 py-4 flex justify-between items-center text-sm font-bold text-slate-800 active:bg-slate-50">
                        <span>查找聊天记录</span>
                        <ChevronRight size={18} className="text-slate-300" />
                    </button>
                    <button className="w-full px-5 py-4 flex justify-between items-center text-sm font-bold text-slate-800 active:bg-slate-50">
                        <span>投诉</span>
                        <ChevronRight size={18} className="text-slate-300" />
                    </button>
                </div>

                <button className="w-full mt-8 bg-white text-rose-500 font-bold py-4 rounded-3xl shadow-sm active:bg-rose-50 transition-colors">删除并退出</button>
             </div>
           </div>
        )}
    </div>
  );
};

export interface ChatViewProps {
  onBack: () => void;
  initialChatId?: string | null;
  onJoinRoom?: (room: Room) => void;
  onCourseClick?: (courseId: string) => void;
}

export default ChatView;

import React, { useState, useRef, useEffect } from 'react';
