               </div>
            </div>
        )}

        {/* Plus Menu */}
        {showPlusMenu && (
            <div className="bg-white border-t border-slate-100 animate-slide-up px-6 pt-8 pb-10 shrink-0 z-20 shadow-[0_-10px_30px_rgba(0,0,0,0.03)]">
