                <button 
                  onClick={() => { setShowPlusMenu(!showPlusMenu); setShowEmojiPicker(false); }}
                  className={`p-2 transition-all duration-300 ${showPlusMenu ? 'text-blue-600 rotate-45' : 'text-slate-400 hover:text-blue-600'}`}
                >
                    <Plus size={28} strokeWidth={1.5} />
                </button>

                <div className="flex-1 bg-[#f1f3f5] rounded-full flex items-center px-4 h-11 transition-all border border-transparent focus-within:border-blue-100 focus-within:bg-[#ebedef]">
                    <input 
                        type="text" 
                        value={inputText}
                        onChange={(e) => setInputText(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleSendText()}
                        onFocus={() => { setShowPlusMenu(false); setShowEmojiPicker(false); }}
                        placeholder="发送消息..."
                        className="flex-1 bg-transparent border-none outline-none text-[15px] text-black placeholder:text-slate-400 font-medium"
                    />
                    <button 
                      onClick={() => { setShowEmojiPicker(!showEmojiPicker); setShowPlusMenu(false); }}
                      className={`ml-2 transition-colors duration-200 ${showEmojiPicker ? 'text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}
                    >
                        <Smile size={24} strokeWidth={1.5} />
                    </button>
                </div>

                <div className="ml-3">
                    {inputText.trim() ? (
                        <button 
                            onClick={handleSendText}
                            className="bg-[#3b82f6] text-white w-11 h-11 rounded-full shadow-lg active:scale-95 animate-scale-in flex items-center justify-center transition-all"
                        >
                            <Send size={20} fill="white" />
                        </button>
                    ) : (
                        <button 
                           onPointerDown={handleMicPointerDown}
                           onPointerMove={handleMicPointerMove}
                           onPointerUp={handleMicPointerUp}
                           onPointerCancel={handleMicPointerUp}
                           className={`w-11 h-11 rounded-full flex items-center justify-center transition-all shadow-md active:scale-90 ${isRecording ? 'bg-rose-500 text-white shadow-rose-200' : 'bg-[#f1f3f5] text-slate-500'}`}
                        >
                            {isRecording ? <Mic size={24} strokeWidth={2.5} className="animate-pulse" /> : <Mic size={24} strokeWidth={1.5} />}
                        </button>
                    )}
                </div>
            </div>
        </div>

        {/* Pickers/Modals */}
        {activePicker !== 'none' && (
          <div className="fixed inset-0 z-[110] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-fade-in" onClick={() => setActivePicker('none')}>
            <div className="bg-white w-full max-sm rounded-[2.5rem] p-6 shadow-2xl animate-scale-in relative overflow-hidden" onClick={e => e.stopPropagation()}>
                <div className="absolute top-0 left-0 w-full h-1.5 bg-gradient-to-r from-blue-600 to-blue-400"></div>
                <button onClick={() => setActivePicker('none')} className="absolute top-5 right-5 text-slate-300 hover:text-slate-900 transition-colors"><X size={22}/></button>

                {activePicker === 'course' && (
                  <div className="flex flex-col h-[70vh]">
                    <h3 className="font-bold text-lg text-black mb-4 flex items-center"><BookOpen size={20} className="mr-2 text-blue-600"/> 推荐课程</h3>
                    <div className="flex-1 overflow-y-auto pr-2 space-y-2 custom-scrollbar">
                       {MOCK_COURSES.map(c => (
                         <div 
                            key={c.id} 
                            onClick={() => sendMessage({ type: 'course', content: c.id })}
                            className="p-3 bg-slate-50 border border-slate-100 rounded-2xl flex items-center cursor-pointer hover:bg-blue-50 transition-colors group"
                         >
                           <img src={c.thumbnail} className="w-12 h-12 rounded-lg object-cover mr-3 shadow-sm"/>
                           <div className="flex-1 min-w-0">
                             <p className="text-sm font-bold text-black truncate">{c.title}</p>
                             <p className="text-[10px] text-slate-400">{c.instructor}</p>
                           </div>
                           <Send size={16} className="text-blue-500 ml-2 opacity-0 group-hover:opacity-100 transition-opacity"/>
                         </div>
                       ))}
                    </div>
                  </div>
                )}

                {activePicker === 'scripture' && (
                  <div>
                    <h3 className="font-bold text-lg text-black mb-4 flex items-center"><Scroll size={20} className="mr-2 text-orange-500"/> 分享经文</h3>
                    <div className="bg-slate-50 rounded-2xl p-4 mb-4 border border-slate-100">
                      <textarea 
                        id="verseInput"
                        className="w-full bg-transparent text-black text-[15px] font-serif min-h-[140px] outline-none border-none placeholder:text-slate-300" 
                        placeholder="输入想要分享的经文内容或金句..."
                        autoFocus
                      />
                    </div>
                    <button 
                      onClick={() => {
                        const val = (document.getElementById('verseInput') as HTMLTextAreaElement).value;
                        if(val.trim()) sendMessage({ type: 'verse', text: val });
                      }}
                      className="w-full bg-orange-500 text-white py-4 rounded-2xl font-bold active:scale-95 transition-transform shadow-lg shadow-orange-500/20"
                    >发送经文</button>
                  </div>
                )}

                {activePicker === 'prayer' && (
                  <div>
                    <h3 className="font-bold text-lg text-black mb-4 flex items-center"><Heart size={20} className="mr-2 text-rose-500" fill="currentColor"/> 发布代祷</h3>
                    <div className="bg-slate-50 rounded-2xl p-4 mb-4 border border-slate-100">
                      <textarea 
                        id="prayerInput"
                        className="w-full bg-transparent text-black text-[15px] min-h-[140px] outline-none border-none placeholder:text-slate-300 font-bold" 
                        placeholder="在此处输入代祷请求..."
                        autoFocus
                      />
                    </div>
                    <button 
                      onClick={() => {
                        const val = (document.getElementById('prayerInput') as HTMLTextAreaElement).value;
                        if(val.trim()) sendMessage({ type: 'prayer', text: val });
                      }}
                      className="w-full bg-rose-500 text-white py-4 rounded-2xl font-bold active:scale-95 transition-transform shadow-lg shadow-rose-500/20"
                    >发起代祷</button>
                  </div>
                )}

                {activePicker === 'question' && (
                  <div>
                    <h3 className="font-bold text-lg text-black mb-1 flex items-center"><QuestionIcon size={20} className="mr-2 text-cyan-600"/> 学术提问</h3>
                    <p className="text-[11px] text-slate-400 mb-4 leading-relaxed">向教授或同学请教关于神学研究、课程作业的问题。</p>
                    <div className="bg-slate-50 rounded-2xl p-4 mb-4 border border-slate-100">
                      <textarea 
                        id="questionInput"
                        className="w-full bg-transparent text-black text-[15px] min-h-[140px] outline-none border-none placeholder:text-slate-300 font-bold" 
                        placeholder="大dasd"
                        autoFocus
                      />
                    </div>
                    <button 
                      onClick={() => {
                        const val = (document.getElementById('questionInput') as HTMLTextAreaElement).value;
                        if(val.trim()) sendMessage({ type: 'question', text: val });
                      }}
                      className="w-full bg-[#13c2c2] text-white py-4 rounded-2xl font-bold active:scale-95 transition-transform shadow-lg shadow-cyan-500/20"
                    >提交问题</button>
                  </div>
                )}

                {activePicker === 'room' && (
                  <div>
                    <h3 className="font-bold text-lg text-black mb-4 flex items-center"><Radio size={20} className="mr-2 text-emerald-500"/> 开启语音房间</h3>
                    <div className="space-y-5">
                      <div>
                        <label className="text-[10px] font-black text-slate-400 mb-2 block uppercase tracking-widest ml-1">房间名称</label>
                        <input 
                          type="text" 
                          value={roomName}
                          onChange={(e) => setRoomName(e.target.value)}
                          className="w-full bg-slate-50 rounded-2xl px-4 py-3.5 text-[15px] text-black outline-none font-bold border border-slate-100 focus:border-emerald-500 focus:bg-white transition-all"
                          placeholder="输入房间名称..."
                        />
                      </div>
                      <div>
                        <label className="text-[10px] font-black text-slate-400 mb-2 block uppercase tracking-widest ml-1">选择主题</label>
                        <div className="grid grid-cols-2 gap-3">
                          {(Object.keys(THEME_CONFIGS) as RoomType[]).map(type => (
                            <button 
                              key={type}
                              onClick={() => setSelectedRoomType(type)}
                              className={`p-3 rounded-2xl border text-left transition-all ${selectedRoomType === type ? 'bg-emerald-50 border-emerald-500 shadow-sm' : 'bg-white border-slate-100 hover:border-slate-200'}`}
                            >
                              <div className={`w-10 h-10 rounded-xl flex items-center justify-center mb-1.5 ${selectedRoomType === type ? 'bg-emerald-500 text-white shadow-md shadow-emerald-500/20' : 'bg-slate-50 text-slate-400'}`}>
                                {React.createElement(THEME_CONFIGS[type].icon, { size: 18 })}
                              </div>
                              <span className={`text-[11px] font-bold ${selectedRoomType === type ? 'text-emerald-900' : 'text-slate-600'}`}>{THEME_CONFIGS[type].label}</span>
                            </button>
                          ))}
                        </div>
                      </div>
                      <button 
                        onClick={handleCreateRoomAction}
                        disabled={!roomName.trim()}
                        className="w-full bg-emerald-500 text-white py-4 rounded-2xl font-bold mt-2 disabled:opacity-50 disabled:shadow-none shadow-lg shadow-emerald-500/20 active:scale-95 transition-transform"
                      >立即创建并发送</button>
                    </div>
                  </div>
                )}

                {activePicker === 'assignment' && (
                   <div className="text-center">
                    <h3 className="font-bold text-lg text-black mb-4 flex items-center justify-center"><ClipboardList size={20} className="mr-2 text-blue-600"/> 递交作业</h3>
                    <div 
                        onClick={() => {
                            const inp = document.createElement('input');
                            inp.type = 'file';
                            inp.onchange = (e) => {
                                const file = (e.target as any).files[0];
                                if(file) {
                                    sendMessage({ type: 'assignment', text: file.name, meta: `${(file.size / 1024).toFixed(1)} KB` });
                                }
                            };
                            inp.click();
                        }}
                        className="p-12 border-2 border-dashed border-slate-200 rounded-[2.5rem] flex flex-col items-center justify-center text-slate-400 bg-slate-50 hover:bg-slate-100 hover:border-blue-400 hover:text-blue-500 transition-all cursor-pointer group"
                    >
                        <FileUp size={56} className="mb-4 text-slate-300 group-hover:text-blue-400 transition-colors" />
                        <span className="text-sm font-black text-slate-600 group-hover:text-blue-600 transition-colors">点击上传作业文件</span>
                        <span className="text-[11px] mt-2 font-medium">支持 PDF, DOCX, ZIP 等格式</span>
                    </div>
                  </div>
                )}
            </div>
          </div>
        )}

        {/* Group Info Drawer */}
        {showGroupInfo && (
           <div className="fixed inset-0 z-[100] bg-white flex flex-col animate-slide-in-right overflow-hidden">
             <div className="bg-white border-b border-slate-100 px-4 py-3 pt-safe-top flex items-center justify-between shrink-0">
               <button onClick={() => setShowGroupInfo(false)} className="p-2 -ml-2 rounded-full hover:bg-slate-100 transition">
                 <ChevronLeft size={24} className="text-slate-800" />
               </button>
               <h2 className="font-bold text-slate-900 text-[15px]">聊天信息</h2>
               <div className="w-8"></div>
             </div>
             <div className="flex-1 overflow-y-auto bg-[#f7f8fa] p-5">
                <div className="bg-white rounded-3xl p-5 mb-4 grid grid-cols-4 gap-y-6">
                    <div className="flex flex-col items-center">
                        <img src={MOCK_USER.avatar} className="w-12 h-12 rounded-xl object-cover shadow-sm mb-1.5" />
                        <span className="text-[10px] font-bold text-slate-500">我</span>
                    </div>
                    <div className="flex flex-col items-center">
                        <img src={activeConv.userAvatar} className="w-12 h-12 rounded-xl object-cover shadow-sm mb-1.5" />
                        <span className="text-[10px] font-bold text-slate-500">{activeConv.userName}</span>
                    </div>
                    <button className="flex flex-col items-center">
                        <div className="w-12 h-12 rounded-xl border-2 border-dashed border-slate-200 flex items-center justify-center text-slate-300 mb-1.5"><Plus size={24}/></div>
                        <span className="text-[10px] font-bold text-slate-400">添加</span>
                    </button>
                </div>

                <div className="bg-white rounded-3xl overflow-hidden divide-y divide-slate-50">
                    <button className="w-full px-5 py-4 flex justify-between items-center text-sm font-bold text-slate-800 active:bg-slate-50">
                        <span>查找聊天记录</span>
                        <ChevronRight size={18} className="text-slate-300" />
                    </button>
                    <button className="w-full px-5 py-4 flex justify-between items-center text-sm font-bold text-slate-800 active:bg-slate-50">
                        <span>投诉</span>
                        <ChevronRight size={18} className="text-slate-300" />
                    </button>
                </div>

                <button className="w-full mt-8 bg-white text-rose-500 font-bold py-4 rounded-3xl shadow-sm active:bg-rose-50 transition-colors">删除并退出</button>
             </div>
           </div>
        )}
    </div>
  );
};

export interface ChatViewProps {
  onBack: () => void;
  initialChatId?: string | null;
  onJoinRoom?: (room: Room) => void;
  onCourseClick?: (courseId: string) => void;
}

export default ChatView;
